import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"17、【随】 震下兑上","description":"周易口诀义 - 17、【随】 震下兑上","frontmatter":{"title":"17、【随】 震下兑上","description":"周易口诀义 - 17、【随】 震下兑上"},"headers":[],"relativePath":"zh/classics/koujueyi/019.md","filePath":"zh/classics/koujueyi/019.md"}'),r={name:"zh/classics/koujueyi/019.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_17、【随】-震下兑上" tabindex="-1">17、【随】 震下兑上 <a class="header-anchor" href="#_17、【随】-震下兑上" aria-label="Permalink to “17、【随】 震下兑上”">​</a></h1><p>彖曰：「随」，刚来而下柔，动而说，随。大亨贞无咎，而天下随时。随时之义大矣哉！</p><p>象曰：泽中有雷，随，君子以向晦入宴息。</p><p>初九：官有渝，贞吉。出门交有功。</p><p>象曰：「官有渝」，从正吉也。「出门交有功」，不失也。</p><p>六二：系小子，失丈夫。</p><p>象曰：「系小子」，弗兼与也。</p><p>六三：系丈夫，失小子，随有求得，利居贞。</p><p>象曰：「系丈夫」，志舍下也。</p><p>九四：随有获，贞凶。有孚在道以明，何咎？</p><p>象曰：「随有获」，其义凶也。「有孚在道」，明功也。</p><p>九五：孚于嘉，吉。</p><p>象曰：「孚于嘉吉」，位正中也。</p><p>上六：拘系之，乃从维之，王用亨于西山。</p><p>象曰：「拘系之」，上穷也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',16)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
